700	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
701	// ---------------------------------------------------------------------------
702	
703	function describeError(e: unknown): string {
704	  return e instanceof Error ? e.message : String(e);
705	}
706	
707	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
708	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
709	  let text: string;
710	  try {
711	    text = await readFile(configPath, 'utf8');
712	  } catch (e) {
713	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
714	  }
715	
716	  let raw: unknown;
717	  try {
718	    raw = JSON.parse(text);
719	  } catch (e) {
720	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
721	  }
722	
723	  try {
724	    return validateConfig(raw);
725	  } catch (e) {
726	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
727	  }
728	}
