1101	// ---------------------------------------------------------------------------
1102	// OpenAPI 请求正文约定导入（import 子命令）
1103	// ---------------------------------------------------------------------------
1104	//
1105	// 读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面路径”为每个场景
1106	// 接口选择文档操作，仅用操作 requestBody 转换出的正文规则替换接口的
1107	// requestBody（保留接口顺序与 responses），把可直接用于 serve / compare 的
1108	// 新场景 JSON 写往 stdout。不监听端口、不联网、不修改输入文件。
1109	//
1110	// 转换约定：
1111	// - 场景每个接口都必须在文档 paths 中找到同路径、同方法的操作，否则拒绝；
1112	// - GET 操作声明 requestBody 拒绝；POST 未声明 requestBody 时移除接口旧规则；
1113	// - POST 的 requestBody 必须 required=true，content 仅含 application/json
1114	//   且带 schema，否则拒绝；
1115	// - schema 支持 object/array/string/number/integer/boolean、递归
1116	//   properties/required/items、布尔 additionalProperties（缺省按 OpenAPI
1117	//   语义为允许，并在输出中显式写出）；title/description/example 与
1118	//   nullable=false 忽略，其余关键字或非法值一律拒绝；
1119	// - 支持本文件内 $ref（按 JSON Pointer 转义解析）：共享引用允许，目标缺失、
1120	//   外部引用与循环引用拒绝并给出引用链；引用节点只含 $ref；
1121	// - 支持纯对象 allOf：组合节点仅含 allOf 与上述注释，分支可引用或嵌套组合，
1122	//   结果取各分支接受集合的交集（同名字段递归相交、number∩integer 取
1123	//   integer、必填合并、各分支额外字段限制同时生效）；空交集或现有规则
1124	//   无法表达时定位原因并拒绝，不扩展规则种类；
1125	// - 未被场景选中的操作与不可达定义不参与转换（其中的错误不影响结果）；
1126	//   全部输入与所选可达定义有效后才输出，成功退出 0，失败退出 2
1127	//   （stderr 指明文件与操作或定义位置，stdout 为空）。
1128	
1129	class ImportError extends Error {
1130	  constructor(message: string) {
1131	    super(message);
1132	    this.name = 'ImportError';
1133	  }
1134	}
1135	
1136	// allOf 交集为空的标记性错误：对象字段合并时，“可选字段的交集为空”在结果
1137	// 拒绝额外字段时可表达为“禁止该字段出现”，只有确实无法表达时才转为拒绝。
1138	class EmptyIntersection extends Error {
1139	  constructor(message: string) {
1140	    super(message);
1141	    this.name = 'EmptyIntersection';
1142	  }
1143	}
1144	
1145	// 转换过程中的规范化规则：与 BodyRule 同构，但 object 的必填名集合单独保存，
1146	// 便于 allOf 交集计算；输出时再展开为场景规则 JSON。
1147	type NormRule =
1148	  | {
1149	      readonly kind: 'object';
1150	      readonly props: ReadonlyMap<string, NormRule>;
1151	      readonly required: ReadonlySet<string>;
1152	      readonly addl: boolean;
1153	    }
1154	  | { readonly kind: 'array'; readonly items: NormRule }
1155	  | { readonly kind: 'string' | 'number' | 'integer' | 'boolean' };
1156	
1157	type NormObject = Extract<NormRule, { kind: 'object' }>;
1158	
1159	interface ImportCtx {
1160	  // 整份 OpenAPI 文档（$ref 解析的根）
1161	  readonly doc: unknown;
1162	  readonly file: string;
1163	}
1164	
1165	function importErrorMessage(ctx: ImportCtx, where: string, message: string): string {
1166	  return where === ''
1167	    ? `OpenAPI 文件 ${ctx.file}：${message}`
1168	    : `OpenAPI 文件 ${ctx.file} 的 ${where}：${message}`;
1169	}
1170	
1171	function importFail(ctx: ImportCtx, where: string, message: string): never {
1172	  throw new ImportError(importErrorMessage(ctx, where, message));
1173	}
1174	
1175	const OPENAPI_ANNOTATION_KEYS: ReadonlySet<string> = new Set([
1176	  'title',
1177	  'description',
1178	  'example',
1179	  'nullable',
1180	]);
1181	
1182	const OPENAPI_SCALAR_TYPES: ReadonlySet<string> = new Set([
1183	  'string',
1184	  'number',
1185	  'integer',
1186	  'boolean',
1187	]);
1188	
1189	function hasOwnKey(value: object, key: string): boolean {
1190	  return Object.prototype.hasOwnProperty.call(value, key);
1191	}
