1193	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1194	function unescapeRefSegment(
1195	  segment: string,
1196	  ref: string,
1197	  ctx: ImportCtx,
1198	  where: string,
1199	): string {
1200	  let out = '';
1201	  for (let i = 0; i < segment.length; i += 1) {
1202	    const ch = segment[i];
1203	    if (ch === '~') {
1204	      const next = segment[i + 1];
1205	      if (next === '0') {
1206	        out += '~';
1207	        i += 1;
1208	      } else if (next === '1') {
1209	        out += '/';
1210	        i += 1;
1211	      } else {
1212	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1213	      }
1214	    } else {
1215	      out += ch;
1216	    }
1217	  }
1218	  return out;
1219	}
