1277	// schema（或引用链尽头的 schema）-> 规范化规则
1278	function schemaToNorm(
1279	  rawNode: unknown,
1280	  ctx: ImportCtx,
1281	  where: string,
1282	  refChain: readonly string[],
1283	): NormRule {
1284	  let node = rawNode;
1285	  let nodeWhere = where;
1286	  let chain = refChain;
1287	  // 引用节点可以层层指向另一个引用节点
1288	  for (;;) {
1289	    if (!isPlainObject(node)) {
1290	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1291	    }
1292	    const ref = dereference(node, ctx, nodeWhere, chain);
1293	    if (!ref) {
1294	      break;
1295	    }
1296	    node = ref.target;
1297	    nodeWhere = ref.where;
1298	    chain = ref.refChain;
1299	  }
1300	  const n = node as Record<string, unknown>;
1301	
1302	  // nullable 仅允许 false（等同不声明，忽略）；true 属于非法值
1303	  if (hasOwnKey(n, 'nullable') && n.nullable !== false) {
1304	    importFail(ctx, `${nodeWhere}.nullable`, `仅支持 false（或不声明），收到 ${JSON.stringify(n.nullable)}`);
1305	  }
1306	
1307	  if (hasOwnKey(n, 'allOf')) {
1308	    for (const key of Object.keys(n)) {
1309	      if (key !== 'allOf' && !OPENAPI_ANNOTATION_KEYS.has(key)) {
1310	        importFail(
1311	          ctx,
1312	          nodeWhere,
1313	          `组合节点仅允许 allOf 及注释（title/description/example/nullable），含未支持的关键字 "${key}"`,
1314	        );
1315	      }
1316	    }
1317	    const list = n.allOf;
1318	    if (!Array.isArray(list) || list.length === 0) {
1319	      importFail(ctx, `${nodeWhere}.allOf`, '必须是非空数组');
1320	    }
1321	    const branches = (list as unknown[]).map((branch, i) =>
1322	      schemaToNorm(branch, ctx, `${nodeWhere}.allOf[${i}]`, chain),
1323	    );
1324	    for (let i = 0; i < branches.length; i += 1) {
1325	      const branch = branches[i] as NormRule;
1326	      if (branch.kind !== 'object') {
1327	        importFail(
1328	          ctx,
1329	          `${nodeWhere}.allOf[${i}]`,
1330	          `仅支持纯对象 allOf 组合，该分支最终类型为 ${branch.kind}`,
1331	        );
1332	      }
1333	    }
1334	    return mergeObjectNorms(branches as NormObject[], ctx, nodeWhere);
1335	  }
1336	
1337	  const type = n.type;
1338	  if (
1339	    typeof type !== 'string' ||
1340	    (type !== 'object' && type !== 'array' && !OPENAPI_SCALAR_TYPES.has(type))
1341	  ) {
1342	    importFail(
1343	      ctx,
1344	      `${nodeWhere}.type`,
1345	      `必须是 "object" | "array" | "string" | "number" | "integer" | "boolean"，收到 ${JSON.stringify(n.type)}`,
1346	    );
1347	  }
1348	  const structural: readonly string[] =
1349	    type === 'object'
1350	      ? ['properties', 'required', 'additionalProperties']
1351	      : type === 'array'
1352	        ? ['items']
1353	        : [];
1354	  for (const key of Object.keys(n)) {
1355	    if (key !== 'type' && !OPENAPI_ANNOTATION_KEYS.has(key) && !structural.includes(key)) {
1356	      importFail(ctx, nodeWhere, `含未支持的关键字 "${key}"`);
1357	    }
1358	  }
1359	
1360	  if (type === 'array') {
1361	    if (!hasOwnKey(n, 'items')) {
1362	      importFail(ctx, `${nodeWhere}.items`, '数组 schema 必须声明元素规则 items');
1363	    }
1364	    return { kind: 'array', items: schemaToNorm(n.items, ctx, `${nodeWhere}.items`, chain) };
1365	  }
1366	
1367	  if (type === 'object') {
1368	    const propsRaw = n.properties;
1369	    if (propsRaw !== undefined && !isPlainObject(propsRaw)) {
1370	      importFail(ctx, `${nodeWhere}.properties`, '必须是对象（字段名 -> schema）');
1371	    }
1372	    const reqRaw = n.required;
1373	    const requiredList: string[] = [];
1374	    if (reqRaw !== undefined) {
1375	      if (!Array.isArray(reqRaw)) {
1376	        importFail(ctx, `${nodeWhere}.required`, '必须是字符串数组');
1377	      }
1378	      for (let i = 0; i < (reqRaw as unknown[]).length; i += 1) {
1379	        const item = (reqRaw as unknown[])[i];
1380	        if (typeof item !== 'string') {
1381	          importFail(ctx, `${nodeWhere}.required[${i}]`, `必须是字符串，收到 ${JSON.stringify(item)}`);
1382	        }
1383	        if (requiredList.includes(item as string)) {
1384	          importFail(ctx, `${nodeWhere}.required`, `含重复项 ${JSON.stringify(item)}`);
1385	        }
1386	        requiredList.push(item as string);
1387	      }
1388	    }
1389	    const props = new Map<string, NormRule>();
1390	    if (propsRaw !== undefined) {
1391	      for (const [name, sub] of Object.entries(propsRaw as Record<string, unknown>)) {
1392	        props.set(
1393	          name,
1394	          schemaToNorm(sub, ctx, `${nodeWhere}.properties[${JSON.stringify(name)}]`, chain),
1395	        );
1396	      }
1397	    }
1398	    for (const name of requiredList) {
1399	      if (!props.has(name)) {
1400	        importFail(ctx, `${nodeWhere}.required`, `${JSON.stringify(name)} 未在同层 properties 中声明`);
1401	      }
1402	    }
1403	    const addlRaw = n.additionalProperties;
1404	    if (addlRaw !== undefined && typeof addlRaw !== 'boolean') {
1405	      importFail(
1406	        ctx,
1407	        `${nodeWhere}.additionalProperties`,
1408	        `仅支持布尔值，收到 ${JSON.stringify(addlRaw)}`,
1409	      );
1410	    }
1411	    // OpenAPI 缺省允许未声明字段；输出时显式写出
1412	    return { kind: 'object', props, required: new Set(requiredList), addl: addlRaw !== false };
1413	  }
1414	
1415	  return { kind: type as 'string' | 'number' | 'integer' | 'boolean' };
1416	}
1417	
1418	// 两个规范化规则的交集；交集为空抛 EmptyIntersection，现有规则种类无法表达
1419	// 时抛 ImportError。
1420	function intersectNorms(a: NormRule, b: NormRule, ctx: ImportCtx, where: string): NormRule {
1421	  if (a.kind === 'object' && b.kind === 'object') {
1422	    return mergeObjectNorms([a, b], ctx, where);
1423	  }
1424	  if (a.kind === 'array' && b.kind === 'array') {
1425	    try {
1426	      return { kind: 'array', items: intersectNorms(a.items, b.items, ctx, `${where}.items`) };
1427	    } catch (e) {
1428	      if (e instanceof EmptyIntersection) {
1429	        throw new ImportError(
1430	          importErrorMessage(
1431	            ctx,
1432	            where,
1433	            `数组元素规则交集为空（${e.message}），交集结果仅含空数组，现有规则种类无法表达`,
1434	          ),
1435	        );
1436	      }
1437	      throw e;
1438	    }
1439	  }
1440	  if (a.kind === 'object' || a.kind === 'array' || b.kind === 'object' || b.kind === 'array') {
1441	    throw new EmptyIntersection(`类型 ${a.kind} 与 ${b.kind} 没有共同接受的值`);
1442	  }
1443	  if (a.kind === b.kind) {
1444	    return a;
1445	  }
1446	  // number 与 integer 相交取 integer；其余标量组合交集为空
1447	  if (
1448	    (a.kind === 'number' && b.kind === 'integer') ||
1449	    (a.kind === 'integer' && b.kind === 'number')
1450	  ) {
1451	    return { kind: 'integer' };
1452	  }
1453	  throw new EmptyIntersection(`类型 ${a.kind} 与 ${b.kind} 没有共同接受的值`);
1454	}
1455	
1456	// 纯对象 allOf 的交集：结果接受集合 = 各分支接受集合的交集。
1457	// - 字段可出现的条件：在每个分支中都已声明，或该分支允许额外字段；
1458	//   必填字段若被某分支禁止出现，则交集为空；
1459	// - 同名字段递归相交（number∩integer 取 integer）；必填取并集；
1460	// - 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）；
1461	// - 可选字段交集为空且结果拒绝额外字段时，不声明该字段即“禁止出现”，
1462	//   集合语义不变；结果允许额外字段时无法表达，拒绝。
1463	function mergeObjectNorms(
1464	  branches: readonly NormObject[],
1465	  ctx: ImportCtx,
1466	  where: string,
1467	): NormObject {
1468	  const addl = branches.every((b) => b.addl);
1469	  const props = new Map<string, NormRule>();
1470	  const required = new Set<string>();
1471	
1472	  const names: string[] = [];
1473	  const seen = new Set<string>();
1474	  for (const branch of branches) {
1475	    for (const name of branch.props.keys()) {
1476	      if (!seen.has(name)) {
1477	        seen.add(name);
1478	        names.push(name);
1479	      }
1480	    }
1481	  }
1482	
1483	  for (const name of names) {
1484	    const fieldWhere = `${where}.properties[${JSON.stringify(name)}]`;
1485	    const isRequired = branches.some((b) => b.required.has(name));
1486	    const permitted = branches.every((b) => b.props.has(name) || b.addl);
1487	    if (!permitted) {
1488	      // 该字段在交集中禁止出现：不声明即可表达（此时必有分支 addl=false，
1489	      // 结果 addl 必为 false）
1490	      if (isRequired) {
1491	        throw new EmptyIntersection(
1492	          `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现（未声明且 additionalProperties 为 false），交集为空`,
1493	        );
1494	      }
1495	      continue;
1496	    }
1497	    let merged: NormRule | undefined;
1498	    for (const branch of branches) {
1499	      const sub = branch.props.get(name);
1500	      if (sub === undefined) {
1501	        continue;
1502	      }
1503	      if (merged === undefined) {
1504	        merged = sub;
1505	        continue;
1506	      }
1507	      try {
1508	        merged = intersectNorms(merged, sub, ctx, fieldWhere);
1509	      } catch (e) {
1510	        if (e instanceof EmptyIntersection) {
1511	          if (isRequired) {
1512	            throw new EmptyIntersection(
1513	              `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${e.message}`,
1514	            );
1515	          }
1516	          if (addl) {
1517	            throw new ImportError(
1518	              importErrorMessage(
1519	                ctx,
1520	                fieldWhere,
1521	                `各分支规则交集为空（${e.message}），且所有分支都允许额外字段，现有规则种类无法表达“禁止该字段出现”`,
1522	              ),
1523	            );
1524	          }
1525	          // 可选字段交集为空且结果拒绝额外字段：不声明该字段即“禁止出现”
1526	          merged = undefined;
1527	          break;
1528	        }
1529	        throw e;
1530	      }
1531	    }
1532	    if (merged !== undefined) {
1533	      props.set(name, merged);
1534	      if (isRequired) {
1535	        required.add(name);
1536	      }
1537	    }
1538	  }
1539	
1540	  return { kind: 'object', props, required, addl };
1541	}
1542	
1543	// 规范化规则 -> 场景规则 JSON（object 显式写出 fields 与 additionalProperties；
1544	// 字段名可能是 ""/"__proto__"/含斜杠波浪号，一律用无原型对象按自有字段构造）
1545	function normToRuleJson(rule: NormRule): Record<string, unknown> {
1546	  switch (rule.kind) {
1547	    case 'object': {
1548	      const fields: Record<string, unknown> = Object.create(null);
1549	      for (const [name, sub] of rule.props) {
1550	        const subJson = normToRuleJson(sub);
1551	        fields[name] = rule.required.has(name) ? { ...subJson, required: true } : subJson;
1552	      }
1553	      return { type: 'object', fields, additionalProperties: rule.addl };
1554	    }
1555	    case 'array':
1556	      return { type: 'array', items: normToRuleJson(rule.items) };
1557	    default:
1558	      return { type: rule.kind };
1559	  }
1560	}
