1729	// 模块级运行时句柄（启动后赋值）
1730	let activeState: LiveState;
1731	let server: http.Server;
1732	let configFile = '';
1733	let shuttingDown = false;
1734	
1735	// 进程内请求记录：与配置版本、序列相互独立，reload 与清空都不影响编号单调
1736	const requestLog = new RequestLog();
1737	
1738	// 尚未发出的延迟响应定时器，关闭时统一取消
1739	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
1740	
1741	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
1742	let reloadChain: Promise<unknown> = Promise.resolve();
1743	
1744	function triggerReload(): Promise<ReloadResult> {
1745	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
1746	    try {
1747	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
1748	      const next = await loadStateFromFile(configFile, activeState.version + 1);
1749	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
1750	      return { ok: true, version: activeState.version };
1751	    } catch (e) {
1752	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
1753	      return { ok: false, version: activeState.version, error: describeError(e) };
1754	    }
1755	  });
1756	  // 失败也不能打断后续 reload 的排队
1757	  reloadChain = job.then(
1758	    () => undefined,
1759	    () => undefined,
1760	  );
1761	  return job;
1762	}
