1778	function versionHeaders(
1779	  version: number,
1780	  extra?: { readonly [name: string]: string },
1781	): { [name: string]: string } {
1782	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
1783	  const headers: { [name: string]: string } = Object.create(null);
1784	  headers[VERSION_HEADER] = String(version);
1785	  if (extra) {
1786	    for (const [name, value] of Object.entries(extra)) {
1787	      headers[name] = value;
1788	    }
1789	  }
1790	  return headers;
1791	}
