1793	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
1794	  writeResponse(
1795	    res,
1796	    status,
1797	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
1798	    `${JSON.stringify(value)}\n`,
1799	  );
1800	}
