// 标量类型交集：相同类型取自身；number ∩ integer 取 integer；其余组合为空。
// 结果与顺序无关。
function scalarIntersection(
  a: NormRule,
  b: NormRule,
): { kind: 'string' | 'number' | 'integer' | 'boolean' } | null {
  if (a.kind === b.kind) {
    return a as { kind: 'string' | 'number' | 'integer' | 'boolean' };
  }
  if (
    (a.kind === 'number' && b.kind === 'integer') ||
    (a.kind === 'integer' && b.kind === 'number')
  ) {
    return { kind: 'integer' };
  }
  return null;
}

// 多个叶分支（全部归一化为对象，可能来自嵌套 allOf）接受集合的交集。
// 必须对“全部分支同时”判定，结论与分支顺序、嵌套分组无关；不可在两两折叠的
// 中途因某个中间交集不可表达就拒绝——再叠加分支后真实交集可能变为可表达
// （例如 string 与 integer 两支本不可表达，第三支是封闭空对象后，交集恰为
// 只接受空对象的封闭对象）。loc 一律给出贡献该结论的叶分支对象级位置。
function intersectObjects(
  flat: readonly FlatBranch[],
  ctx: ImportCtx,
  where: string,
): Intersection {
  // 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）
  const addl = flat.every((b) => b.rule.addl);

  const names: string[] = [];
  const seen = new Set<string>();
  for (const branch of flat) {
    for (const name of branch.rule.props.keys()) {
      if (!seen.has(name)) {
        seen.add(name);
        names.push(name);
      }
    }
  }

  const props = new Map<string, NormRule>();
  const required = new Set<string>();
  // 非空但无法表达时的首个原因与位置（可能随后被收窄为空交集）
  let inex: { reason: string; loc: string } | undefined;

  const noteInexpressible = (reason: string, loc: string): void => {
    if (inex === undefined) {
      inex = { reason, loc };
    }
  };

  for (const name of names) {
    const fieldWhere = `${where}.properties[${JSON.stringify(name)}]`;
    const isRequired = flat.some((b) => b.rule.required.has(name));

    // 声明了该字段、从而真正约束其取值的分支；未声明但允许额外字段的分支放行
    const declarers = flat.filter((b) => b.rule.props.has(name));

    // 该字段被某分支禁止出现（未声明且该分支 additionalProperties 为 false）
    const forbidden = flat.some((b) => !b.rule.props.has(name) && !b.rule.addl);
    if (forbidden) {
      if (isRequired) {
        const fb = flat.find((b) => !b.rule.props.has(name) && !b.rule.addl) as FlatBranch;
        return {
          tag: 'empty',
          reason:
            `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现` +
            '（未声明且 additionalProperties 为 false），交集为空',
          loc: fb.where,
        };
      }
      // 可选且被禁止：结果中不声明该字段即“禁止出现”。即便其余声明分支的取值
      // 交集为空/不可表达也无关紧要——该字段根本不能出现（其中的非法 schema
      // 仍在 schemaToNorm 阶段被拒绝，不会走到这里）。
      continue;
    }

    // 没有任何分支声明它：仅靠“允许额外字段”放行，交集对它无约束，不写入结果
    if (declarers.length === 0) {
      continue;
    }

    const sub = intersectRules(
      declarers.map((b) => ({ rule: b.rule.props.get(name) as NormRule, where: b.where })),
      ctx,
      fieldWhere,
    );

    if (sub.tag === 'empty') {
      if (isRequired) {
        return {
          tag: 'empty',
          reason: `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${sub.reason}`,
          loc: sub.loc,
        };
      }
      // 可选字段交集为空：结果拒绝额外字段时，不声明即“禁止出现”，可表达；
      if (!addl) {
        continue;
      }
      // 所有分支都允许额外字段时，无法表达“该字段禁止出现而其他字段任意”
      noteInexpressible(
        `可选字段 ${JSON.stringify(name)} 的各分支规则交集为空（${sub.reason}），` +
          '且所有分支都允许额外字段，现有规则种类无法表达“仅禁止该字段出现”',
        sub.loc,
      );
      continue;
    }

    if (sub.tag === 'inexpressible') {
      // 子级非空但不可表达；本字段可选时外层封闭也许能补救，故带着近似规则继续
      if (isRequired) {
        noteInexpressible(
          `必填字段 ${JSON.stringify(name)} 的各分支规则交集非空但无法表达：${sub.reason}`,
          sub.loc,
        );
      } else {
        noteInexpressible(
          `可选字段 ${JSON.stringify(name)} 的各分支规则交集非空但无法表达：${sub.reason}`,
          sub.loc,
        );
      }
      props.set(name, sub.rule.rule);
      if (isRequired) {
        required.add(name);
      }
      continue;
    }

    props.set(name, sub.rule);
    if (isRequired) {
      required.add(name);
    }
  }

  const merged: NormObject = { kind: 'object', props, required, addl };
  if (inex !== undefined) {
    return { tag: 'inexpressible', rule: merged, reason: inex.reason, loc: inex.loc };
  }
  return { tag: 'nonempty', rule: merged };
}

// 多个叶分支规则（标量/数组/对象）的交集，三态返回，结论与顺序、分组无关。
function intersectRules(
  flat: readonly { readonly rule: NormRule; readonly where: string }[],
  ctx: ImportCtx,
  where: string,
): Intersection {
  const first = flat[0].rule;

  // 任一两两类型不一致即交集为空；记录首个与首分支类型不同的分支位置
  for (let i = 1; i < flat.length; i += 1) {
    if (flat[i].rule.kind !== first.kind) {
      return {
        tag: 'empty',
        reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
        loc: flat[i].where,
      };
    }
  }

  if (first.kind === 'object') {
    return intersectObjects(flat as unknown as FlatBranch[], ctx, where);
  }

  if (first.kind === 'array') {
    // 元素规则的交集整体判定；数组只接受“每个元素都在交集中”的序列：
    // - 元素交集可表达 -> 非空（空数组总被接受），items 取交集；
    // - 元素交集为空 -> 仅剩空数组，现有规则种类无法表达；
    // - 元素交集非空但不可表达 -> 同样无法在不扩展规则种类的前提下表达。
    const itemFlat = flat.map((b, i) => ({
      rule: (b.rule as Extract<NormRule, { kind: 'array' }>).items,
      where: `${b.where}（数组元素）`,
    }));
    const itemsWhere = `${where}.items`;
    const itemRes = intersectRules(itemFlat, ctx, itemsWhere);
    const approxArray: NormRule = {
      kind: 'array',
      items:
        itemRes.tag === 'nonempty'
          ? itemRes.rule
          : itemRes.tag === 'inexpressible'
            ? itemRes.rule
            : (itemFlat[0].rule as NormRule),
    };
    if (itemRes.tag === 'empty') {
      return {
        tag: 'inexpressible',
        rule: approxArray,
        reason: `数组元素规则交集为空（${itemRes.reason}），交集仅含空数组，现有规则种类无法表达`,
        loc: itemRes.loc,
      };
    }
    if (itemRes.tag === 'inexpressible') {
      return {
        tag: 'inexpressible',
        rule: approxArray,
        reason: `数组元素规则交集非空但无法表达：${itemRes.reason}`,
        loc: itemRes.loc,
      };
    }
    return { tag: 'nonempty', rule: { kind: 'array', items: itemRes.rule } };
  }

  // 标量：顺序无关地求类型交集；遇空即整体为空
  let acc: NormRule = first;
  for (let i = 1; i < flat.length; i += 1) {
    const hit = scalarIntersection(acc, flat[i].rule);
    if (hit === null) {
      return {
        tag: 'empty',
        reason: `类型 ${acc.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
        loc: flat[i].where,
      };
    }
    acc = hit;
  }
  return { tag: 'nonempty', rule: acc };
}

// 把（可能嵌套的）allOf 分支树展平为叶对象分支列表：组合节点只含 allOf 与
// 注释，其叶分支就是该子树的全部对象分支，交集天然满足结合律，故展平不改变
// 接受集合，也使结论与嵌套分组无关。where 保留每个叶分支的原始位置用于定位。
function flattenObjectBranches(
  rule: NormRule,
  ctx: ImportCtx,
  where: string,
): FlatBranch[] {
  if (rule.kind !== 'object') {
    importFail(ctx, where, `仅支持纯对象 allOf 组合，该分支最终类型为 ${rule.kind}`);
  }
  return [{ rule: rule as NormObject, where }];
}

