    // loc 指向贡献该结论的叶分支（可定位的操作或定义位置）
    if (result.tag === 'empty' || result.tag === 'inexpressible') {
      importFail(ctx, result.loc, result.reason);
    }
    return result.rule;
  }

  return buildSimpleNorm(n, ctx, nodeWhere, chain);
}

